//预处理程序
bool preProcess(const string fileName, const string newFileName) {
	ifstream inFile(fileName);
	if (!inFile) {
		cout << "无法打开文件：" << fileName << endl;
		return false;
	}
	//读取整个文件内容
	stringstream buffer;
	buffer << inFile.rdbuf();
	string str = buffer.str();
	inFile.close();

	//去除注释
	string noComment;
	for (size_t i = 0; i < str.length(); i++) {
		if (str[i] == '/' && i + 1 < str.length() && str[i + 1] == '/') {
			//单行注释，跳到行尾
			while (i < str.length() && str[i] != '\n') i++;
		}
		else if (str[i] == '/' && i + 1 < str.length() && str[i + 1] == '*') {
			//多行注释，跳到*/
			i += 2;
			while (i + 1 < str.length() && !(str[i] == '*' && str[i + 1] == '/')) i++;
			i++;
		}
		else {
			noComment += str[i];
		}
	}

	//规范化空白字符
	string normalized;
	bool lastSpace = false;
	for (size_t i = 0; i < noComment.length(); i++) {
		char c = noComment[i];
		if (c == '\n' || c == '\r' || c == '\t') continue;
		if (c == ' ') {
			if (lastSpace || normalized.empty()) continue;
			lastSpace = true;
			normalized += c;
		}
		else {
			lastSpace = false;
			normalized += c;
		}
	}
	//去掉末尾空格
	while (!normalized.empty() && normalized.back() == ' ') normalized.pop_back();

	printTips("预处理");
	//打印预处理后的字符流
	for (size_t i = 0; i < normalized.length(); i++) {
		cout << normalized[i];
	}
	cout << endl;

	ofstream outFile(newFileName);
	outFile << normalized;
	outFile.close();
	return true;
}
